package com.smartmart.wishlist.repository; import com.smartmart.wishlist.entity.Wishlist; import org.springframework.data.jpa.repository.JpaRepository; import java.util.*; public interface WishlistRepository extends JpaRepository<Wishlist,Long>{List<Wishlist> findByUserIdOrderByCreatedAtDesc(Long id); boolean existsByUserIdAndProductId(Long user,Long product); void deleteByUserIdAndProductId(Long user,Long product);}
